async function main() {
  console.log('AI Mastery for Professionals — Supabase Insert');
  console.log('===============================================\n');

  const { data: existing } = await supabase
    .from('courses')
    .select('id, slug, title')
    .eq('slug', COURSE.slug)
    .maybeSingle();

  const payload = {
    ...COURSE,
    long_description,
    why_section,
    how_section,
    what_section,
    objectives,
  };

  if (existing) {
    console.log(`Updating: ${existing.title} (${existing.id})`);
    const { error } = await supabase
      .from('courses')
      .update(payload)
      .eq('slug', COURSE.slug);
    if (error) { console.error(error.message); process.exit(1); }
    console.log('Updated successfully.');
  } else {
    console.log('Inserting new course...');
    const { data, error } = await supabase
      .from('courses')
      .insert(payload)
      .select('id, slug')
      .single();
    if (error) { console.error(error.message); process.exit(1); }
    console.log(`Inserted: id=${data.id}`);
  }

  console.log('\nSummary:');
  console.log('  slug:          ', COURSE.slug);
  console.log('  category:      ', COURSE.category);
  console.log('  why_section:   ', why_section.length, 'items');
  console.log('  how_section:   ', how_section.length, 'items');
  console.log('  what_section:  ', what_section.length, 'items');
  console.log('  objectives:    ', objectives.length, 'modules');
  console.log('\nURL: https://capvisionpartner.com/courses/' + COURSE.slug);
}

main();
